insert into powers (id, name, description) values
  ('zoning-land-use', 'Approve zoning, land-use plans and permits', 'Decides what may be built where, through zoning, land-use plans and building permits.'),
  ('rent-tenant-rules', 'Set rent rules and tenant protections', 'Sets local rules on rent and tenant protections where state law allows.'),
  ('housing-court', 'Decide eviction and housing cases', 'Hears and decides eviction and other housing cases.'),
  ('building-energy-codes', 'Adopt building and energy codes', 'Adopts the building and energy codes new and renovated buildings must meet.'),
  ('utility-rates', 'Set electric, gas and water rates for regulated utilities', 'Approves or rejects the rates that regulated utilities may charge their customers.'),
  ('utility-resource-plans', 'Approve power plants and clean-energy plans', 'Approves utilities'' plans for new power plants, closures and clean-energy targets.'),
  ('large-load-contracts', 'Decide who pays for data center and large-load grid costs', 'Decides the terms on which very large electricity users, such as data centers, pay for the grid they need.'),
  ('public-power-governance', 'Run a public or member-owned utility: rates, power supply, shutoffs', 'Governs a public or member-owned utility, including its rates, where it buys power and its shutoff rules.'),
  ('oil-gas-permits', 'Permit and regulate drilling and pipelines', 'Issues and enforces permits for oil and gas drilling and pipelines.'),
  ('state-land-leasing', 'Lease public land for energy, minerals and grazing', 'Decides how public land is leased for energy, mining and grazing.'),
  ('tax-abatements', 'Grant tax abatements and incentive deals', 'Grants or refuses tax abatements and incentive deals for businesses.'),
  ('school-tax-abatements', 'Approve abatements that cut school revenue', 'Approves or refuses tax abatements that reduce school district revenue.'),
  ('property-assessment', 'Set property valuations', 'Sets the assessed value of property on which property taxes are charged.'),
  ('assessment-appeals', 'Hear assessment appeals and equalize values', 'Hears appeals of property assessments and evens out values across owners.'),
  ('property-tax-levy', 'Set property tax rates and levies', 'Sets property tax rates and the total amount levied.'),
  ('local-wage-labor-standards', 'Set local wage, leave and contractor standards', 'Sets local minimum wage, paid leave and contractor labor standards where state law allows.'),
  ('labor-law-enforcement', 'Enforce wage and labor law', 'Investigates and enforces wage and labor laws.'),
  ('public-employee-bargaining', 'Bargain with and set pay for public workers', 'Negotiates with and sets pay for the public body''s own workers.'),
  ('charging-decisions', 'Decide which cases to charge or decline', 'Decides which criminal cases to charge, and which to decline or drop.'),
  ('jail-and-patrol', 'Run the jail and county law enforcement', 'Runs the county jail and county law enforcement.'),
  ('police-jail-budget', 'Set police and jail budgets and oversight', 'Sets police and jail budgets and oversees how they are spent.'),
  ('bail-and-sentencing', 'Set bail and sentences', 'Sets bail and imposes sentences in criminal cases.'),
  ('public-hospital-governance', 'Govern public hospitals and charity care', 'Governs public hospitals, including their charity care policies.'),
  ('public-health-programs', 'Fund health departments and care for the uninsured', 'Funds the health department and care for people without insurance.'),
  ('insurance-rate-review', 'Approve or reject insurer rates', 'Approves or rejects the rates insurers may charge.'),
  ('state-health-law', 'Pass state health law: Medicaid, mandates, public option, single payer', 'Passes state health law, including Medicaid rules, coverage mandates, a public option or single payer.'),
  ('federal-legislation', 'Vote on federal law and spending', 'Votes on federal laws and federal spending.'),
  ('school-governance', 'Set school budgets and policy, hire the superintendent', 'Sets the school district''s budget and policies and hires its superintendent.'),
  ('state-education-policy', 'Set statewide school standards and funding rules', 'Sets statewide school standards and the rules for school funding.'),
  ('water-supply-rates', 'Set water rates and allocate water to large users', 'Sets water rates and decides how much water large users may take.'),
  ('soil-water-conservation', 'Direct conservation and watershed programs', 'Directs local soil, water and watershed conservation programs.'),
  ('transit-service-fares', 'Set transit routes, fares and capital plans', 'Sets transit routes, fares and plans for new lines and vehicles.'),
  ('local-transport-funding', 'Fund streets, bus lanes and local transit', 'Funds streets, bus lanes and local transit.'),
  ('election-administration', 'Run elections: rolls, polling places, mail ballots, certification', 'Runs elections, including voter rolls, polling places, mail ballots and certification.'),
  ('election-rules-enforcement', 'Set statewide election rules and enforce campaign finance law', 'Sets statewide election rules and enforces campaign finance law.'),
  ('local-campaign-finance', 'Set local public financing, contribution limits and disclosure', 'Sets local public campaign financing, contribution limits and disclosure rules.'),
  ('party-nominations', 'Fill vacancies, endorse, pick delegates and party officers', 'Fills party vacancies, makes endorsements and picks delegates and party officers.'),
  ('poll-worker-appointments', 'Name poll workers and election board members', 'Names poll workers and members of election boards.'),
  ('public-fund-investment', 'Invest and bank public money, including bond purchases', 'Invests and banks public money, including which bonds it buys.'),
  ('pension-investment', 'Set pension investment and divestment policy', 'Sets how a public pension fund invests and what it divests from.'),
  ('state-legislation', 'Pass state law and budgets, including rules that preempt or free local action', 'Passes state laws and budgets, including laws that limit or allow local action.')
